package com.cinenest.pricing.internal;
import com.cinenest.identity.ScopedAuthorization;
import com.cinenest.rooms.PackageConstraints;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service
@Transactional
class DraftService {
 private final DraftRepository repository;private final ScopedAuthorization authorization;private final PackageConstraints constraints;
 DraftService(DraftRepository repository,ScopedAuthorization authorization,PackageConstraints constraints){this.repository=repository;this.authorization=authorization;this.constraints=constraints;}
 private void require(UUID actor,UUID venue,String action,boolean lock){if(!authorization.permits(actor,venue,action,lock))throw new DraftFailure(403,"Access denied");}
 private Map<String,Object> raw(UUID v,UUID id){return repository.find(v,id,false).orElseThrow(()->new DraftFailure(404,"Draft not found"));}
 private Map<String,Object> present(UUID actor,UUID v,Map<String,Object>d){d.put("permittedActions",authorization.permits(actor,v,"package.edit",false)?List.of("package.read","package.edit"):List.of("package.read"));d.put("canPublish",authorization.permits(actor,v,"package.publish",false));d.put("publicationImplemented",true);return d;}
 Map<String,Object> list(UUID actor,UUID v,String q,int page,int size){require(actor,v,"package.read",false);if(q.length()>200||page<0||size<1||size>100)throw DraftRules.invalid("filters");var result=repository.list(v,q.trim(),page,size);result.put("permittedActions",authorization.permits(actor,v,"package.edit",false)?List.of("package.read","package.edit"):List.of("package.read"));result.put("canPublish",false);return result;}
 Map<String,Object> read(UUID actor,UUID v,UUID id){require(actor,v,"package.read",false);return present(actor,v,raw(v,id));}
 Map<String,Object> history(UUID actor,UUID v,UUID id,int page,int size){require(actor,v,"package.read",false);if(page<0||size<1||size>100)throw DraftRules.invalid("history paging");raw(v,id);return repository.history(v,id,page,size);}
 Map<String,Object> options(UUID actor,UUID v){require(actor,v,"package.read",false);var facts=constraints.inspect(v,Set.of(),true,false);Map<String,Object> out=new LinkedHashMap<>();out.put("services",repository.options(v));out.put("constraints",facts.orElse(null));out.put("constraintStatus",facts.isPresent()?"CONFIGURED":"MISSING_POLICY_OR_ROOMS");return out;}
 private PackageConstraints.Facts facts(UUID v,Map<String,Object>d,boolean lock){boolean wide=DraftRules.flag(d,"venueWide");Set<UUID> rooms=DraftRules.roomIds(d);if(wide&&!rooms.isEmpty())throw DraftRules.invalid("venueWide/roomIds");return constraints.inspect(v,rooms,wide,lock).orElseThrow(()->new DraftFailure(400,"Approved minimum policy and compatible rooms required"));}
 private Map<String,Object> validate(UUID v,Map<String,Object> input,boolean create){
  DraftRules.keys(input,create?new String[]{"code","name","description","currency","basePriceMinor","includedMinutes","minimumMinutes","maximumMinutes","extensionsEnabled","extensionStepMinutes","extensionPriceMinor","includedGuests","maximumGuests","extraGuestPriceMinor","venueWide","roomIds","options","reason"}:new String[]{"code","name","description","currency","basePriceMinor","includedMinutes","minimumMinutes","maximumMinutes","extensionsEnabled","extensionStepMinutes","extensionPriceMinor","includedGuests","maximumGuests","extraGuestPriceMinor","venueWide","roomIds","options","reason","expectedRevision"});
  var d=new HashMap<>(input);d.put("code",DraftRules.code(d));d.put("name",DraftRules.text(d,"name",200,true));d.put("description",DraftRules.text(d,"description",2000,false));DraftRules.neutral(d.get("name")+" "+d.get("description"));DraftRules.text(d,"reason",500,true);
  if(!"LKR".equals(d.get("currency")))throw DraftRules.invalid("currency");DraftRules.minor(d.get("basePriceMinor"),true);DraftRules.minor(d.get("extraGuestPriceMinor"),false);
  int included=DraftRules.integer(d,"includedMinutes",1,Integer.MAX_VALUE),min=DraftRules.integer(d,"minimumMinutes",1,Integer.MAX_VALUE),max=DraftRules.integer(d,"maximumMinutes",1,Integer.MAX_VALUE);
  if(min>included||max<included)throw DraftRules.invalid("duration bounds");boolean extensions=DraftRules.flag(d,"extensionsEnabled");
  if(extensions){int step=DraftRules.integer(d,"extensionStepMinutes",1,Integer.MAX_VALUE);DraftRules.minor(d.get("extensionPriceMinor"),false);if((max-included)%step!=0)throw DraftRules.invalid("extension units");}else if(max!=included||d.get("extensionStepMinutes")!=null||d.get("extensionPriceMinor")!=null)throw DraftRules.invalid("disabled extensions");
  int guests=DraftRules.integer(d,"includedGuests",1,Integer.MAX_VALUE),maximum=DraftRules.integer(d,"maximumGuests",1,Integer.MAX_VALUE);if(maximum<guests)throw DraftRules.invalid("guest bounds");
  var facts=facts(v,d,true);if(included<Math.max(min,facts.minimumMinutes()))throw DraftRules.invalid("venue minimum duration");for(var room:facts.rooms())if(maximum>room.capacity())throw DraftRules.invalid("room capacity");
  Set<UUID> services=new HashSet<>();var options=DraftRules.objects(d,"options");var allowed=repository.options(v);
  for(var option:options){DraftRules.keys(option,"serviceId","rateVersionId","mode");UUID service=DraftRules.id(DraftRules.text(option,"serviceId",36,true)),rate=DraftRules.id(DraftRules.text(option,"rateVersionId",36,true));if(!services.add(service)||!List.of("INCLUDED","OPTIONAL").contains(option.get("mode")))throw DraftRules.invalid("option exclusivity");
   var match=allowed.stream().filter(x->service.equals(x.get("serviceId"))&&rate.equals(x.get("rateVersionId"))).findFirst().orElseThrow(()->DraftRules.invalid("approved service/rate"));DraftRules.neutral((String)match.get("label"));for(var room:facts.rooms())if(!room.facilities().contains(match.get("requiredFacilityCode")))throw DraftRules.invalid("service compatibility");
  }
  long ceiling=DraftRules.minor(d.get("basePriceMinor"),true);
  if(extensions)ceiling=DraftRules.add(ceiling,DraftRules.multiply((max-included)/((Number)d.get("extensionStepMinutes")).intValue(),DraftRules.minor(d.get("extensionPriceMinor"),false)));
  ceiling=DraftRules.add(ceiling,DraftRules.multiply(maximum-guests,DraftRules.minor(d.get("extraGuestPriceMinor"),false)));
  for(var option:options)if(option.get("mode").equals("OPTIONAL")){var rate=allowed.stream().filter(x->x.get("rateVersionId").toString().equals(option.get("rateVersionId"))).findFirst().orElseThrow();ceiling=DraftRules.add(ceiling,DraftRules.minor(rate.get("unitPriceMinor"),false));}
  d.put("options",options);d.put("policyId",facts.policyId());d.put("policyRevision",facts.policyRevision());d.put("constraintFacts",facts);if(!create)DraftRules.revision(d,"expectedRevision");return d;
 }
 Map<String,Object> save(UUID actor,UUID v,UUID id,Map<String,Object> input,boolean create){require(actor,v,"package.edit",true);if(!create)repository.find(v,id,true).orElseThrow(()->new DraftFailure(404,"Draft not found"));var d=validate(v,input,create);long expected=create?-1:DraftRules.revision(d,"expectedRevision");repository.save(v,id,d,create);var saved=raw(v,id);String reason=DraftRules.text(d,"reason",500,true);repository.history(actor,id,saved,reason);repository.audit(actor,v,id,create?"CREATE":"EDIT",true,create?null:expected,((Number)saved.get("revision")).longValue(),reason);if(!facts(v,d,true).equals(d.get("constraintFacts")))throw new DraftFailure(409,"Room/policy changed; revalidate draft");return present(actor,v,saved);}
 Map<String,Object> duplicate(UUID actor,UUID v,UUID id,Map<String,Object> request){require(actor,v,"package.edit",true);DraftRules.keys(request,"code","reason","expectedRevision");var source=raw(v,id);if(((Number)source.get("revision")).longValue()!=DraftRules.revision(request,"expectedRevision"))throw new DraftFailure(409,"Source draft changed");Map<String,Object>d=editable(source);d.put("code",request.get("code"));d.put("reason",request.get("reason"));return save(actor,v,UUID.randomUUID(),d,true);}
 static Map<String,Object> editable(Map<String,Object> source){var d=new HashMap<>(source);for(String key:List.of("packageId","venueId","revision","policyId","policyRevision","status","taxStatus","permittedActions","canPublish","publicationImplemented"))d.remove(key);d.put("roomIds",((List<?>)source.get("roomIds")).stream().map(Object::toString).toList());var opts=new ArrayList<Map<String,Object>>();for(var o:DraftRules.objects(source,"options")){o.put("serviceId",o.get("serviceId").toString());o.put("rateVersionId",o.get("rateVersionId").toString());opts.add(o);}d.put("options",opts);return d;}
 Map<String,Object> preview(UUID actor,UUID v,UUID id,Map<String,Object> input){require(actor,v,"package.read",true);DraftRules.keys(input,"expectedRevision","selectedMinutes","guests");var source=raw(v,id);if(DraftRules.revision(input,"expectedRevision")!=((Number)source.get("revision")).longValue())throw new DraftFailure(409,"Draft changed");var d=editable(source);d.put("expectedRevision",source.get("revision"));d.put("reason","Draft preview");d=validate(v,d,false);
  int duration=input.containsKey("selectedMinutes")?DraftRules.integer(input,"selectedMinutes",1,Integer.MAX_VALUE):(int)d.get("includedMinutes"),guests=input.containsKey("guests")?DraftRules.integer(input,"guests",1,Integer.MAX_VALUE):(int)d.get("includedGuests");
  int extra=duration-(int)d.get("includedMinutes");if(extra<0||duration>(int)d.get("maximumMinutes")||guests>(int)d.get("maximumGuests"))throw DraftRules.invalid("preview selection");long known=DraftRules.minor(d.get("basePriceMinor"),true);
  if(extra>0){if(!(boolean)d.get("extensionsEnabled")||extra%(int)d.get("extensionStepMinutes")!=0)throw DraftRules.invalid("extension units");known=DraftRules.add(known,DraftRules.multiply(extra/(int)d.get("extensionStepMinutes"),DraftRules.minor(d.get("extensionPriceMinor"),false)));}
  known=DraftRules.add(known,DraftRules.multiply(Math.max(0,guests-(int)d.get("includedGuests")),DraftRules.minor(d.get("extraGuestPriceMinor"),false)));
  List<Map<String,Object>> illustrations=new ArrayList<>();var refs=repository.options(v);for(var o:DraftRules.objects(d,"options")){var ref=refs.stream().filter(x->x.get("rateVersionId").toString().equals(o.get("rateVersionId"))).findFirst().orElseThrow();illustrations.add(Map.of("serviceId",ref.get("serviceId").toString(),"label",ref.get("label"),"mode",o.get("mode"),"additionalChargeMinor",o.get("mode").equals("INCLUDED")?"0":ref.get("unitPriceMinor"),"selected",o.get("mode").equals("INCLUDED")));}
  return Map.of("label","DRAFT PREVIEW - NOT FOR SALE / NOT A CHECKOUT QUOTATION","currency","LKR","knownPackageComponentsMinor",Long.toString(known),"taxStatus","UNRESOLVED","feeStatus","UNRESOLVED","options",illustrations,"policyId",d.get("policyId"),"policyRevision",d.get("policyRevision"),"canPublish",false);
 }
}
